import fs from 'node:fs/promises';
import { chromium } from 'playwright';
const ROOT='k9-dog-gear', NAME='K9 / Dog Gear';
const URL=`https://www.statesideqm.com/collections/${ROOT}?preview_theme_id=158561894555`;
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
async function one(browser,label,viewport){
 const ctx=await browser.newContext({viewport}),page=await ctx.newPage(),pageerrors=[];page.on('pageerror',e=>pageerrors.push(e.message));const r=await page.goto(URL,{waitUntil:'domcontentloaded',timeout:45000});try{await page.waitForFunction(()=>document.querySelector('#MainContent')?.dataset.sqRefineV3Ready==='true',{timeout:20000})}catch{}
 const samples=[];const start=Date.now();for(const ms of [1000,5000,9000,13000,17000]){const wait=start+ms-Date.now();if(wait>0)await sleep(wait);samples.push(await page.evaluate(ms=>{const vis=e=>{if(!e)return false;const s=getComputedStyle(e),r=e.getBoundingClientRect();return s.display!=='none'&&s.visibility!=='hidden'&&r.width>0&&r.height>0};const m=document.querySelector('#MainContent'),side=m?.querySelector('.sq-refine-v3-sidebar'),results=m?.querySelector('.sq-refine-v3-results'),grid=results?.querySelector('.product-grid'),component=results?.querySelector('collection-component'),column=results?.querySelector('.sq-collection-products-column'),cat=[...(side?.querySelectorAll('.sq-refine-v3-group')||[])].find(g=>/shop by category/i.test(g.querySelector('summary')?.textContent||''));return{ms,ready:m?.dataset.sqRefineV3Ready||'',cleanup:m?.dataset.sqRefineV3RootCleanup||'',isolation:document.querySelector('[data-sq-refine-v3-legacy-isolation]')?.dataset.sqRefineV3LegacyIsolation||'',grid:vis(grid),cards:grid?.querySelectorAll(':scope>.product-grid__item').length||0,cols:grid?getComputedStyle(grid).gridTemplateColumns.split(' ').filter(Boolean).length:0,component:!!component,column:!!column,categoryCount:cat?.querySelectorAll('input[type="checkbox"]').length||0,legacy:[...document.querySelectorAll('[data-sq-refine-v3-hidden-nav="true"]')].filter(vis).length};},ms));}
 const last=samples.at(-1), errors=[];if((r?.status()||0)>=400)errors.push('HTTP '+r.status());for(const x of pageerrors)errors.push('pageerror '+x);if(last.ready!=='true'||last.cleanup!=='true'||last.isolation!==ROOT)errors.push('guards');if(!last.grid||last.cards!==50)errors.push('grid/cards '+last.cards);const want=label==='mobile'?2:3;if(last.grid&&last.cols!==want)errors.push('columns '+last.cols);if(last.categoryCount!==8)errors.push('categories '+last.categoryCount);if(last.legacy)errors.push('legacy '+last.legacy);for(const s of samples.filter(s=>s.ms>=9000)){if(!s.grid||s.cards!==50||!s.column)errors.push(`unstable@${s.ms}:${s.cards}/${s.column}`)}await fs.mkdir('cert-k9-dog-gear',{recursive:true});await page.screenshot({path:`cert-k9-dog-gear/${label}.png`,fullPage:true});await ctx.close();return{label,http:r?.status()||0,pageerrors,samples,errors};
}
const b=await chromium.launch({headless:true});const report={route:NAME,desktop:await one(b,'desktop',{width:1440,height:1000}),mobile:await one(b,'mobile',{width:390,height:844})};await b.close();report.pass=!report.desktop.errors.length&&!report.mobile.errors.length;await fs.writeFile('cert-k9-dog-gear/report.json',JSON.stringify(report,null,2));console.log(JSON.stringify(report,null,2));if(!report.pass)process.exitCode=1;
